static Matrix getImageRotation(File file) {
  try {
    ExifInterface exif = new ExifInterface(file.getAbsolutePath());
    int orientation = exif.getAttributeInt(ExifInterface.TAG_ORIENTATION, ExifInterface.ORIENTATION_UNDEFINED);
    Matrix matrix = new Matrix();
    switch (orientation) {
      case ExifInterface.ORIENTATION_NORMAL: return null;
      case ExifInterface.ORIENTATION_FLIP_HORIZONTAL: matrix.setScale(-1, 1); return matrix;
      case ExifInterface.ORIENTATION_FLIP_VERTICAL: matrix.setRotate(180); matrix.postScale(-1, 1); return matrix;
      case ExifInterface.ORIENTATION_TRANSPOSE: matrix.setRotate(90); matrix.postScale(-1, 1); return matrix;
      case ExifInterface.ORIENTATION_TRANSVERSE: matrix.setRotate(-90); matrix.postScale(-1, 1); return matrix;
      case ExifInterface.ORIENTATION_ROTATE_90: matrix.setRotate(90); return matrix;
      case ExifInterface.ORIENTATION_ROTATE_180: matrix.setRotate(180); return matrix;
      case ExifInterface.ORIENTATION_ROTATE_270: matrix.setRotate(-90); return matrix;
      default: return null;
    }
  } catch (RuntimeException ex) {
    Log.w(ex);
    return null;
  }
}
